        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import * as React from 'react'
import { cn } from '@/lib/utils'
import { CheckIcon } from 'lucide-react'
import { Checkbox as CheckboxPrimitive } from 'radix-ui'

function Checkbox({ className, ...props }: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        'peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs transition-shadow outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:data-[state=checked]:bg-primary',
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none"
      >
        <CheckIcon className="size-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }
/**
 * Presents independently selectable labeled options and emits the complete selected-value array. An optional label names the group for assistive technology.
 */
export function CheckboxGroup({
  options,
  value = [],
  onValueChange,
  disabled,
  label,
}: {
  options: { value: string; label: React.ReactNode; disabled?: boolean }[]
  value?: string[]
  onValueChange?: (value: string[]) => void
  disabled?: boolean
  label?: string
}) {
  return (
    <div role="group" aria-label={label} className="flex flex-wrap gap-4">
      {options.map((option) => (
        <label key={option.value} className="flex items-center gap-2 text-sm">
          <Checkbox
            checked={value.includes(option.value)}
            disabled={disabled || option.disabled}
            onCheckedChange={(checked) =>
              onValueChange?.(
                checked ? [...value, option.value] : value.filter((v) => v !== option.value),
              )
            }
          />
          {option.label}
        </label>
      ))}
    </div>
  )
}

import * as React from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { cn } from '@/lib/utils'
export interface ListProps<T> {
  items: T[]
  getKey: (item: T) => string
  renderItem: (item: T, index: number) => React.ReactNode
  empty?: React.ReactNode
  className?: string
  grid?: boolean
  virtual?: boolean
  height?: number
  estimateSize?: number
  hasMore?: boolean
  loading?: boolean
  onLoadMore?: () => void | Promise<void>
}
export function List<T>({
  items,
  getKey,
  renderItem,
  empty = 'No items to display',
  className,
  grid,
  virtual,
  height = 400,
  estimateSize = 80,
  hasMore,
  loading,
  onLoadMore,
}: ListProps<T>) {
  const root = React.useRef<HTMLDivElement>(null),
    sentinel = React.useRef<HTMLDivElement>(null),
    [width, setWidth] = React.useState(0),
    [pending, setPending] = React.useState(false),
    columns = grid && width >= 540 ? 2 : 1
  React.useEffect(() => {
    if (!root.current) return
    const observer = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width))
    observer.observe(root.current)
    return () => observer.disconnect()
  }, [])
  const load = React.useCallback(async () => {
    if (!hasMore || loading || pending || !onLoadMore) return
    setPending(true)
    try {
      await onLoadMore()
    } finally {
      setPending(false)
    }
  }, [hasMore, loading, pending, onLoadMore])
  React.useEffect(() => {
    if (!sentinel.current || !hasMore) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) void load()
      },
      { root: virtual ? root.current : null, rootMargin: '100px' },
    )
    observer.observe(sentinel.current)
    return () => observer.disconnect()
  }, [load, hasMore, virtual])
  const list = useVirtualizer({
    count: Math.ceil(items.length / columns),
    getScrollElement: () => root.current,
    estimateSize: () => estimateSize,
    overscan: 4,
    enabled: !!virtual,
    initialRect: { width: 600, height },
  })
  const item = (record: T, index: number) => (
    <div
      role="listitem"
      key={getKey(record)}
      aria-posinset={index + 1}
      aria-setsize={items.length}
      className={cn('p-4', grid ? 'rounded-lg border' : 'border-b last:border-0')}
    >
      {renderItem(record, index)}
    </div>
  )
  return (
    <div
      ref={root}
      tabIndex={virtual ? 0 : undefined}
      aria-label={virtual ? 'Scrollable collection' : undefined}
      className={cn(virtual && 'overflow-auto', className)}
      style={virtual ? { height } : undefined}
      onScroll={() => {
        const el = root.current
        if (virtual && el && el.scrollHeight - el.scrollTop - el.clientHeight < 100) void load()
      }}
    >
      {items.length ? (
        <div
          role="list"
          aria-busy={loading || pending}
          className={cn('relative', !grid && 'rounded-lg border', grid && !virtual && 'grid gap-3')}
          style={
            virtual
              ? { height: list.getTotalSize() }
              : grid
                ? { gridTemplateColumns: `repeat(${columns},minmax(0,1fr))` }
                : undefined
          }
        >
          {virtual
            ? list.getVirtualItems().map((row) => (
                <div
                  key={row.key}
                  data-index={row.index}
                  ref={list.measureElement}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    transform: `translateY(${row.start}px)`,
                    display: grid ? 'grid' : 'block',
                    gridTemplateColumns: `repeat(${columns},minmax(0,1fr))`,
                    gap: 12,
                  }}
                  role="presentation"
                >
                  {items
                    .slice(row.index * columns, (row.index + 1) * columns)
                    .map((record, i) => item(record, row.index * columns + i))}
                </div>
              ))
            : items.map(item)}
        </div>
      ) : (
        <div className="p-10 text-center text-sm text-muted-foreground">{empty}</div>
      )}
      <div ref={sentinel}>
        {(loading || pending) && (
          <p role="status" className="p-3 text-center text-xs">
            Loading more…
          </p>
        )}
        {hasMore && (
          <button
            type="button"
            disabled={loading || pending}
            onClick={() => void load()}
            className="w-full p-3 text-xs text-primary"
          >
            Load more
          </button>
        )}
      </div>
    </div>
  )
}
